func countWords(words []string) map[string]int {
    var counts map[string]int
    for _, w := range words {
        counts[w]++
    }
    return counts
}

func report(counts map[string]int) string {
    out := ""
    for w, n := range counts {
        out += fmt.Sprintf("%s=%d ", w, n)
    }
    return out
}
